require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('student');$q=db()->prepare('SELECT p.id,p.title,p.status,p.reference_no,d.name department,pr.name programme,ac.name session_name,CONCAT_WS(" ",su.first_name,su.last_name) supervisor FROM projects p JOIN project_members pm ON pm.project_id=p.id JOIN departments d ON d.id=p.department_id LEFT JOIN programmes pr ON pr.id=p.programme_id LEFT JOIN academic_sessions ac ON ac.id=p.academic_session_id LEFT JOIN project_supervisors ps ON ps.project_id=p.id AND ps.ended_at IS NULL LEFT JOIN users su ON su.id=ps.supervisor_id WHERE pm.student_id=? ORDER BY p.created_at DESC LIMIT 1');$q->execute([$u['id']]);$project=$q->fetch();$pid=(int)($project['id']??0);$err='';$maxUploadMb=max(1,min(50,(int)app_setting('max_upload_mb',(string)(MAX_UPLOAD_BYTES/1048576))));$maxUploadBytes=$maxUploadMb*1048576;
$ideaSelected=false;$finalChecklist=[];$finalReady=false;
if($pid){$q=db()->prepare("SELECT COUNT(*) FROM project_ideas WHERE project_id=? AND review_status='approved'");$q->execute([$pid]);$ideaSelected=(int)$q->fetchColumn()>0;$finalChecklist['Project idea selected']=$ideaSelected;foreach(['proposal'=>'Proposal','chapter_1'=>'Chapter 1','chapter_2'=>'Chapter 2','chapter_3'=>'Chapter 3','chapter_4'=>'Chapter 4','chapter_5'=>'Chapter 5'] as $type=>$label){$q=db()->prepare('SELECT status FROM submissions WHERE project_id=? AND document_type=? ORDER BY submitted_at DESC LIMIT 1');$q->execute([$pid,$type]);$finalChecklist[$label.' approved']=$q->fetchColumn()==='approved';}$finalReady=!in_array(false,$finalChecklist,true);}
$submissionStatus=[];$canSubmit=[];$stageRows=[];$hasSupervisor=!empty($project['supervisor']);$ideaReviewStatus='pending';
if($pid){$q=db()->prepare('SELECT document_type,status FROM submissions WHERE project_id=? AND student_id=?');$q->execute([$pid,$u['id']]);foreach($q->fetchAll() as $row)$submissionStatus[$row['document_type']]=$row['status'];$iq=db()->prepare('SELECT review_status FROM project_ideas WHERE project_id=? ORDER BY id');$iq->execute([$pid]);$ideaStatuses=$iq->fetchAll(PDO::FETCH_COLUMN);if($ideaSelected)$ideaReviewStatus='approved';elseif(in_array('revision_requested',$ideaStatuses,true))$ideaReviewStatus='revision_required';elseif($ideaStatuses)$ideaReviewStatus='under_review';$lockedStatuses=['submitted','resubmitted','under_review','approved'];$canSubmit['proposal']=$ideaSelected&&$hasSupervisor&&!in_array($submissionStatus['proposal']??'', $lockedStatuses,true);$previous=['chapter_1'=>'proposal','chapter_2'=>'chapter_1','chapter_3'=>'chapter_2','chapter_4'=>'chapter_3','chapter_5'=>'chapter_4'];foreach($previous as $type=>$prev)$canSubmit[$type]=($submissionStatus[$prev]??'')==='approved'&&!in_array($submissionStatus[$type]??'',$lockedStatuses,true);$canSubmit['final_project']=$finalReady&&!in_array($submissionStatus['final_project']??'',$lockedStatuses,true);$canSubmit['supporting_document']=!in_array($submissionStatus['supporting_document']??'',$lockedStatuses,true);$stageDefinition=[['Project idea','idea'],['Proposal','proposal'],['Chapter 1','chapter_1'],['Chapter 2','chapter_2'],['Chapter 3','chapter_3'],['Chapter 4','chapter_4'],['Chapter 5','chapter_5'],['Final submission','final_project']];foreach($stageDefinition as [$label,$type]){if($type==='idea'){$stageState=$ideaReviewStatus;$canAct=false;}else{$status=$submissionStatus[$type]??'';$stageState=$status?:($canSubmit[$type]?'ready':'locked');$canAct=(bool)$canSubmit[$type];}$stageRows[]=['label'=>$label,'type'=>$type,'state'=>$stageState,'can_submit'=>$canAct];}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$type=(string)($_POST['document_type']??'');$allowed=['proposal','chapter_1','chapter_2','chapter_3','chapter_4','chapter_5','final_project','supporting_document'];$f=$_FILES['document']??null;$stageError='';if($type==='proposal'&&!$ideaSelected)$stageError='Your supervisor must select one project idea before proposal submission opens.';elseif($type==='proposal'&&(!$project||!$hasSupervisor||!in_array($project['status'],['supervisor_assigned','proposal_submitted','in_progress','correction_required','final_submission','under_evaluation'],true)))$stageError='Proposal submission opens after your supervisor selects an idea and is assigned to the project.';elseif($type==='final_project'&&!$finalReady)$stageError='The final document remains locked until the idea, proposal, and Chapters 1–5 are approved.';elseif(in_array($type,['chapter_1','chapter_2','chapter_3','chapter_4','chapter_5'],true)){$previous=['chapter_1'=>'proposal','chapter_2'=>'chapter_1','chapter_3'=>'chapter_2','chapter_4'=>'chapter_3','chapter_5'=>'chapter_4'][$type];$q=db()->prepare('SELECT status FROM submissions WHERE project_id=? AND document_type=? ORDER BY submitted_at DESC LIMIT 1');$q->execute([$pid,$previous]);if($q->fetchColumn()!=='approved')$stageError='The previous project stage must be approved before this document can be submitted.';}
 if(!$stageError&&in_array($submissionStatus[$type]??'', ['submitted','resubmitted','under_review'],true))$stageError='This stage already has a version waiting for supervisor review.';elseif(!$stageError&&($submissionStatus[$type]??'')==='approved')$stageError='This stage is already approved. Its previous versions remain available in your history.';
 if(!$pid||!in_array($type,$allowed,true))$err='Project or document type is invalid.';
