 else {$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$docBytes=file_get_contents($f['tmp_name'],false,null,0,8);$docMagic=bin2hex($docBytes?:'')==='d0cf11e0a1b11ae1';$docOk=$ext!=='doc'||$mime==='application/msword'||(($mime==='application/octet-stream'||$mime==='application/x-ole-storage')&&$docMagic);$docxOk=true;if($ext==='docx'){if(class_exists('ZipArchive')){$zip=new ZipArchive();$opened=$zip->open($f['tmp_name'])===true;$docxOk=$opened&&$zip->locateName('[Content_Types].xml')!==false&&$zip->locateName('word/document.xml')!==false;if($opened)$zip->close();}else{$docxOk=false;}}$valid=['pdf'=>['application/pdf'],'doc'=>['application/msword','application/octet-stream','application/x-ole-storage'],'docx'=>['application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/zip','application/octet-stream']];if(!isset($valid[$ext])||!in_array($mime,$valid[$ext],true)||!$docxOk||!$docOk)$err='Only valid PDF, DOC, and DOCX documents are accepted.';
  else {try{$dir=UPLOAD_ROOT.DIRECTORY_SEPARATOR.date('Y').DIRECTORY_SEPARATOR.$pid;if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))throw new RuntimeException('Cannot create upload directory');$safe=bin2hex(random_bytes(24)).'.'.$ext;$dest=$dir.DIRECTORY_SEPARATOR.$safe;if(!move_uploaded_file($f['tmp_name'],$dest))throw new RuntimeException('Cannot move upload');$relative=date('Y').'/'.$pid.'/'.$safe;db()->beginTransaction();$q=db()->prepare('SELECT id,current_version,status FROM submissions WHERE project_id=? AND student_id=? AND document_type=? ORDER BY id DESC LIMIT 1');$q->execute([$pid,$u['id'],$type]);$s=$q->fetch();if(!$s){db()->prepare('INSERT INTO submissions(project_id,student_id,document_type,status,current_version) VALUES(?,?,?,"submitted",1)')->execute([$pid,$u['id'],$type]);$sid=(int)db()->lastInsertId();$ver=1;}else{$sid=(int)$s['id'];$ver=(int)$s['current_version']+1;db()->prepare('UPDATE submissions SET current_version=?,status="resubmitted",submitted_at=NOW() WHERE id=?')->execute([$ver,$sid]);}$q=db()->prepare('INSERT INTO submission_versions(submission_id,version_number,original_filename,stored_filename,storage_path,file_size_bytes,mime_type,file_sha256,uploaded_by,change_note) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$sid,$ver,basename($f['name']),$safe,$relative,(int)$f['size'],$mime,hash_file('sha256',$dest),$u['id'],post_string('change_note',1000)]);db()->prepare("UPDATE corrections c JOIN submission_reviews r ON r.id=c.submission_review_id JOIN submission_versions v ON v.id=r.submission_version_id SET c.status='resubmitted' WHERE v.submission_id=? AND c.status IN ('open','in_progress')")->execute([$sid]);db()->commit();audit('document_submitted','submission',$sid,"{$type} version {$ver} uploaded");$q=db()->prepare('SELECT supervisor_id FROM project_supervisors WHERE project_id=? AND ended_at IS NULL');$q->execute([$pid]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $sid2)notify_user((int)$sid2,'Submission received',"A {$type} document has been submitted.",'action','submission',$sid);flash('success','Your submission was uploaded successfully.');redirect($type==='final_project'?'student/final-submission.php':'student/submissions.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();error_log($e->getMessage());$err='Upload failed. Please try again.';}}
 }
