$q=db()->prepare('SELECT s.*,v.id version_id,v.version_number,v.original_filename,v.uploaded_at,v.file_size_bytes FROM submissions s JOIN submission_versions v ON v.submission_id=s.id WHERE s.project_id=? ORDER BY s.submitted_at DESC,v.version_number DESC');$q->execute([$pid]);$rows=$q->fetchAll();$selectedType=(string)($_GET['type']??'');if(!in_array($selectedType,['proposal','chapter_1','chapter_2','chapter_3','chapter_4','chapter_5','final_project','supporting_document'],true))$selectedType='';$showFormEarly=($err!=='')||isset($_GET['new'])||$selectedType!==''||$_SERVER['REQUEST_METHOD']==='POST';$pageTitle=$selectedType==='final_project'?'Final Submission':($showFormEarly?'Upload Academic Work':'Submission Record Logs');$crumbTrail=$selectedType==='final_project'?['Submissions','Final submission']:($showFormEarly?['Submissions','New submission']:['Submissions','History']);require dirname(__DIR__).'/includes/header.php';
